uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_fov;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_tunnel_twist;
uniform float u_triangle_size;
uniform float u_kaleidoscope_segments;

out vec4 fragColor;

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Kaleidoscope function to fold space into N segments
vec2 kaleidoscope(vec2 p, float segments) {
    float a = atan(p.y, p.x);
    float r = length(p);
    float segmentAngle = 3.14159265 * 2.0 / segments;
    a = mod(a, segmentAngle) - segmentAngle * 0.5;
    a = abs(a);
    return vec2(cos(a), sin(a)) * r;
}

// Signed Distance Function for an equilateral triangle prism
float sdTrianglePrism(vec2 p, float r) {
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * sign(p.y);
}

// Smooth Minimum for blending shapes
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Universe Path - The world curves slightly to create an infinite feeling
vec2 getPath(float z) {
    return vec2(sin(z * 0.12) * 3.5, cos(z * 0.08) * 2.5);
}

// Distance Field
float map(vec3 p) {
    // Offset the entire world by the path
    vec2 path = getPath(p.z);
    p.xy -= path;

    // Apply Kaleidoscope folding
    p.xy = kaleidoscope(p.xy, u_kaleidoscope_segments);

    // Twist the coordinate system along the Z axis
    float angle = p.z * u_tunnel_twist + iTime * 0.2;
    p.xy *= rot(angle);

    // Create the Triangle Tunnel
    // Negative because we are inside the prism
    float triangle = -sdTrianglePrism(p.xy, u_triangle_size);

    // Add internal floating triangle rings
    vec3 p_rings = p;
    float ringZ = 6.0;
    float ringId = floor(p_rings.z / ringZ);
    p_rings.z = mod(p_rings.z, ringZ) - ringZ * 0.5;

    // Alternate rotation for rings
    p_rings.xy *= rot(ringId * 1.5 + iTime);
    float rings = max(abs(sdTrianglePrism(p_rings.xy, u_triangle_size * 0.7)) - 0.1, abs(p_rings.z) - 0.2);

    // Floating orbs that follow the path center
    vec3 p_spheres = p;
    p_spheres.z = mod(p_spheres.z + 4.0, 8.0) - 4.0;
    p_spheres.y += sin(iTime + p.z * 0.5) * 1.0;
    float spheres = length(p_spheres) - 0.4;

    // Combine everything
    float scene = min(triangle, rings);
    scene = smin(scene, spheres, 0.8);

    return scene;
}

// Standard normal calculation
vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.01, 0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // 2. Fly-through timing
    float t = iTime * u_speed;

    // 3. Parallel Rail Camera Setup
    vec3 pathPos = vec3(0.0, 0.0, t);
    pathPos.xy += getPath(pathPos.z);

    // The Rail: Camera orbits the path center
    vec2 railVec = vec2(sin(t * 0.2), cos(t * 0.2)) * (u_camera_dist * 0.5);

    vec3 ro = pathPos;
    ro.xy += railVec;

    // Target: Look ahead
    vec3 ta = vec3(0.0, 0.0, t + 10.0);
    ta.xy += getPath(ta.z); 

    // Camera Basis
    vec3 fwd = normalize(ta - ro);
    vec3 right = normalize(cross(vec3(0, 1, 0), fwd));
    vec3 up = cross(fwd, right);
    vec3 rd = normalize(fwd * u_fov + uv.x * right + uv.y * up);

    // 4. Raymarching Loop
    float d = 0.0;
    float t_dist = 0.1;
    float glow = 0.0;

    for(int i = 0; i < 90; i++) {
        vec3 p = ro + rd * t_dist;
        d = map(p);

        // Accumulate glow based on proximity to the geometric edges
        glow += exp(-max(d, 0.0) * 1.2) * u_glow_intensity;

        if(abs(d) < 0.001 || t_dist > 80.0) break;
        t_dist += d * 0.7; 
    }

    // 5. Coloring and Shading
    vec3 col = vec3(0.0);
    vec3 p = ro + rd * t_dist;

    // Base Gradient Colors
    vec3 skyTop = vec3(0.05, 0.02, 0.1);
    vec3 skyBottom = vec3(0.2, 0.05, 0.4);
    vec3 neonColor = vec3(0.2, 0.8, 1.0);

    if(t_dist < 80.0) {
        vec3 n = getNormal(p);
        float diff = max(dot(n, normalize(vec3(1, 2, -1))), 0.0);
        float fresnel = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);

        // Procedural color based on rotation/twist
        float hue = sin(p.z * 0.05 + iTime * 0.2) * 0.5 + 0.5;
        vec3 objCol = mix(vec3(0.1, 0.05, 0.2), vec3(0.4, 0.1, 0.6), hue);

        // Add metallic/neon edges
        objCol = mix(objCol, neonColor, fresnel * 0.8);

        col = objCol * (diff + 0.1);

        // Specular highlights
        col += vec3(1.0, 0.9, 0.8) * pow(max(dot(reflect(rd, n), normalize(vec3(0,1,0))), 0.0), 16.0);
    } else {
        // Background Gradient
        col = mix(skyBottom, skyTop, uv.y + 0.5);
    }

    // 6. Volumetric Fog & Glowing Atmosphere
    float fog = 1.0 - exp(-t_dist * 0.03);
    vec3 fogCol = mix(vec3(0.01, 0.0, 0.05), vec3(0.2, 0.05, 0.3), sin(t * 0.05) * 0.5 + 0.5);
    col = mix(col, fogCol, fog);

    // Apply the neon glow
    col += mix(vec3(1.0, 0.2, 0.5), neonColor, sin(t * 0.5) * 0.5 + 0.5) * glow * 0.05;

    // 7. Post-Processing
    col = smoothstep(-0.02, 1.05, col); // Soft contrast
    col *= 1.2 - length(uv) * 0.6;      // Stronger Vignette

    // Noise/Grain
    float grain = texture(iChannel0, uv * 3.0 + t * 0.05).r;
    col += (grain - 0.5) * 0.04;

    fragColor = vec4(col, 1.0);
}
